	if err:=registry.Bind("identity.profile.update",func(ctx context.Context,inv Invocation,value any)(OperationResult,error){if inv.Actor.CredentialKind!=CredentialSession{return OperationResult{},ErrForbidden};profile,err:=services.Identity.UpdateCurrentProfilePreferences(ctx,inv.Actor.IdentityContext(),inv.Request.ExpectedGeneration,profilePreferencesPatch(value.(*ProfilePreferencesUpdatePayload)));if err!=nil{return OperationResult{},mapIdentityError(err)};return OperationResult{Status:http.StatusOK,Value:profilePreferencesProjection(profile),Generation:profile.Revision},nil});err!=nil{return err}
	if err:=registry.Bind("identity.profile.admin.get",func(ctx context.Context,inv Invocation,_ any)(OperationResult,error){tenantID,_:=identity.NewID(inv.Request.TenantID);principalID,_:=identity.NewID(inv.Request.ResourceID);profile,err:=services.Identity.ProfilePreferencesForAdmin(ctx,inv.Actor.IdentityContext(),tenantID,principalID);if err!=nil{return OperationResult{},mapIdentityError(err)};return OperationResult{Status:http.StatusOK,Value:adminProfilePreferencesProjection(profile),Generation:profile.Revision},nil});err!=nil{return err}
	if err:=registry.Bind("identity.profile.admin.update",func(ctx context.Context,inv Invocation,value any)(OperationResult,error){if inv.Actor.CredentialKind!=CredentialSession{return OperationResult{},ErrForbidden};tenantID,_:=identity.NewID(inv.Request.TenantID);principalID,_:=identity.NewID(inv.Request.ResourceID);profile,err:=services.Identity.UpdateProfilePreferencesForAdmin(ctx,inv.Actor.IdentityContext(),tenantID,principalID,inv.Request.ExpectedGeneration,profilePreferencesPatch(value.(*ProfilePreferencesUpdatePayload)));if err!=nil{return OperationResult{},mapIdentityError(err)};return OperationResult{Status:http.StatusOK,Value:adminProfilePreferencesProjection(profile),Generation:profile.Revision},nil});err!=nil{return err}
	if err:=registry.Bind("identity.support_grant.issue",func(ctx context.Context,inv Invocation,value any)(OperationResult,error){if inv.Actor.CredentialKind!=CredentialSession{return OperationResult{},ErrForbidden};payload:=value.(*SupportGrantIssuePayload);grantID,_:=identity.NewID(commandID(inv));tenantID,_:=identity.NewID(inv.Request.TenantID);resourceID,_:=identity.NewID(payload.ResourceID);permissions:=make([]identity.Permission,0,len(payload.Permissions));for _,raw:=range payload.Permissions{permission,err:=identity.NewPermission(raw);if err!=nil{return OperationResult{},ErrInvalidRequest};permissions=append(permissions,permission)};issued,err:=services.Identity.IssueSupportGrant(ctx,identity.IssueSupportGrantCommand{Actor:inv.Actor.IdentityContext(),GrantID:grantID,TargetTenantID:tenantID,Scope:identity.Scope{Kind:payload.ScopeKind,TenantID:tenantID,ResourceID:resourceID},Permissions:permissions,Reason:payload.Reason,ExpiresAt:payload.ExpiresAt});if err!=nil{return OperationResult{},mapIdentityError(err)};secret:=string(issued.Secret);clearSecret(issued.Secret);return OperationResult{Status:http.StatusCreated,Value:SupportGrantIssueResult{Grant:supportGrantProjection(issued.Grant),Secret:secret},Generation:issued.Grant.Generation},nil});err!=nil{return err}
	if err:=registry.Bind("identity.support_grant.list",func(ctx context.Context,inv Invocation,value any)(OperationResult,error){tenantID,_:=identity.NewID(inv.Request.TenantID);payload:=value.(*SupportGrantPagePayload);cursor,err:=optionalSessionID(payload.Cursor);if err!=nil{return OperationResult{},ErrInvalidRequest};grants,next,total,err:=services.Identity.ListSupportGrants(ctx,inv.Actor.IdentityContext(),tenantID,int(payload.Limit),cursor);if err!=nil{return OperationResult{},mapIdentityError(err)};items:=make([]SupportGrantProjection,0,len(grants));for _,grant:=range grants{items=append(items,supportGrantProjection(grant))};return OperationResult{Status:http.StatusOK,Value:SupportGrantPageResult{Items:items,NextCursor:next,Total:total}},nil});err!=nil{return err}
	if err:=registry.Bind("identity.support_grant.get",func(ctx context.Context,inv Invocation,_ any)(OperationResult,error){tenantID,_:=identity.NewID(inv.Request.TenantID);grantID,_:=identity.NewID(inv.Request.ResourceID);grant,err:=services.Identity.GetSupportGrant(ctx,inv.Actor.IdentityContext(),tenantID,grantID);if err!=nil{return OperationResult{},mapIdentityError(err)};return OperationResult{Status:http.StatusOK,Value:supportGrantProjection(grant),Generation:grant.Generation},nil});err!=nil{return err}
	if err:=registry.Bind("identity.support_grant.revoke",func(ctx context.Context,inv Invocation,_ any)(OperationResult,error){if inv.Actor.CredentialKind!=CredentialSession{return OperationResult{},ErrForbidden};tenantID,_:=identity.NewID(inv.Request.TenantID);grantID,_:=identity.NewID(inv.Request.ResourceID);grant,err:=services.Identity.RevokeSupportGrant(ctx,inv.Actor.IdentityContext(),tenantID,grantID,inv.Request.ExpectedGeneration);if err!=nil{return OperationResult{},mapIdentityError(err)};return OperationResult{Status:http.StatusOK,Value:supportGrantProjection(grant),Generation:grant.Generation},nil});err!=nil{return err}
	if err:=registry.Bind("identity.support_grant.accept",func(ctx context.Context,inv Invocation,value any)(OperationResult,error){if inv.Actor.CredentialKind!=CredentialSession{return OperationResult{},ErrForbidden};tenantID,_:=identity.NewID(inv.Request.TenantID);grantID,_:=identity.NewID(inv.Request.ResourceID);payload:=value.(*SupportGrantAcceptPayload);secret:=[]byte(payload.Secret);payload.Secret="";defer clearSecret(secret);supportContext,err:=services.Identity.AcceptSupportGrant(ctx,inv.Actor.IdentityContext(),tenantID,grantID,inv.Request.ExpectedGeneration,secret);if err!=nil{return OperationResult{},mapIdentityError(err)};return OperationResult{Status:http.StatusCreated,Value:supportContextProjection(supportContext)},nil});err!=nil{return err}
	if err:=registry.Bind("identity.session.webauthn.begin",func(ctx context.Context,inv Invocation,value any)(OperationResult,error){rpID,err:=webAuthnRP(inv.Meta);if err!=nil{return OperationResult{},err};challenge,err:=services.Identity.BeginWebAuthnLogin(ctx,value.(*WebAuthnLoginBeginPayload).Username,rpID);if err!=nil{return OperationResult{},mapIdentityError(err)};options:=append(json.RawMessage(nil),challenge.PublicKeyOptions...);clearSecret(challenge.PublicKeyOptions);return OperationResult{Status:http.StatusOK,Value:WebAuthnLoginBeginResult{ChallengeID:challenge.ChallengeID.String(),PublicKey:options,ExpiresAt:challenge.ExpiresAt}},nil});err!=nil{return err}
	if err:=registry.Bind("identity.session.webauthn.finish",func(ctx context.Context,inv Invocation,value any)(OperationResult,error){if _,err:=webAuthnRP(inv.Meta);err!=nil{return OperationResult{},err};payload:=value.(*WebAuthnLoginFinishPayload);challenge,_:=identity.NewID(payload.ChallengeID);response:=append([]byte(nil),payload.Response...);clearSecret(payload.Response);result,err:=services.Identity.CompleteWebAuthnLogin(ctx,challenge,response,inv.Meta.ClientIP,inv.Meta.UserAgentDigest,30*time.Minute,12*time.Hour);clearSecret(response);if err!=nil{return OperationResult{},mapIdentityError(err)};viewer,err:=services.Identity.CurrentViewer(ctx,loginActor(result));if err!=nil{return OperationResult{},mapIdentityError(err)};return loginResult(result,viewer)});err!=nil{return err}
